230	/// Refresh `Cargo.lock` for the workspace's own packages, offline, so
231	/// a `--locked` build finds the version the manifest now has.
232	fn refresh_lock(root: &Path) -> Result<(), String> {
233	    // `CARGO` is the cargo that runs this task, absent only when the
234	    // binary is run by hand.
235	    let cargo = match std::env::var_os("CARGO") {
236	        Some(cargo) => cargo,
237	        None => "cargo".into(),
238	    };
239	    // The root's clippy.toml bans spawning for `vc-x1`, which goes
240	    // through jj-lib. A project task running cargo is the exception.
241	    #[allow(clippy::disallowed_methods)]
242	    let status = std::process::Command::new(cargo)
243	        .args(["update", "--workspace", "--offline", "--quiet"])
244	        .current_dir(root)
245	        .status()
246	        .map_err(|e| format!("cargo update did not run: {e}"))?;
247	    match status.success() {
248	        true => Ok(()),
249	        false => Err(format!(
250	            "cargo update --workspace --offline failed: {status}"
251	        )),
252	    }
253	}
