//! The work's tasks: validate, build, run, and install, each run
//! through cargo with the build's provenance in its environment.
//!
//! - The provenance, `VC_X1_BUILD_COMMIT` and `VC_X1_BUILD_STATE`, is
//!   read through `jj`: `@-`'s commit, and `clean` when `@` is empty,
//!   `dirty` when not. vc-x1's `build.rs` compiles them into its
//!   banner, `0.85.25+<commit>.dirty`, and reruns when they change, so
//!   every task sets the same values and none recompiles for another.
//!   A provenance that cannot be read is a warning, and the build
//!   carries git's `HEAD` and `.unknown`, as a plain `cargo build`
//!   does.
//! - A profile is Cargo's, `[profile.<name>]` in `Cargo.toml`, `dev`
//!   and `release` built in. Its binary is in cargo's target directory,
//!   `debug` for `dev` and `test`, `release` for `bench`, and the
//!   profile's own name for any other.
//! - `build` and `run` default to `dev`, as `cargo build` and `cargo
//!   run` do, and `install` to `release`, the binary other sessions
//!   use.
//! - `install` names the copy by the profile: `vc-x1` for `release` and
//!   `vc-x1-<name>` for any other, so a dev build sits beside the
//!   release and never replaces it.
//! - `run`'s words after its own flags are the binary's, and so is
//!   their completion: [`forward_completion`] asks the built binary.

use std::ffi::{OsStr, OsString};
use std::path::{Path, PathBuf};
use std::process::Command;

/// The binary the tasks build, run, and install.
pub const BIN: &str = "vc-x1";

/// The variable carrying the build's commit to cargo.
const COMMIT_VAR: &str = "VC_X1_BUILD_COMMIT";

/// The variable carrying the state of the source code being compiled.
const STATE_VAR: &str = "VC_X1_BUILD_STATE";

/// The full validation, each element one invocation of cargo.
const FULL: &[&[&str]] = &[
    &["fmt"],
    &["clippy", "--all-targets", "--", "-D", "warnings"],
    &["test", "--", "--include-ignored"],
];

/// The fast validation, the binaries' unit tests alone.
const FAST: &[&[&str]] = &[&["test", "--bins"]];

/// A process to spawn.
///
/// The root's clippy.toml bans spawning for `vc-x1`, which goes through
/// jj-lib. A project task running cargo, jj, or the binary it built is
/// the exception, and this is the one site.
#[allow(clippy::disallowed_methods)]
fn command(program: impl AsRef<OsStr>) -> Command {
    Command::new(program)
}

/// The cargo that runs this task, `cargo` when the binary is run by
/// hand.
pub fn cargo() -> OsString {
    match std::env::var_os("CARGO") {
        Some(cargo) => cargo,
        None => "cargo".into(),
    }
}

/// What a build is made from.
#[derive(Debug, PartialEq, Eq)]
pub struct Provenance {
    /// The full commit id of the work repo's `@-`.
    pub commit: String,
    /// `clean` when `@` is empty, else `dirty`.
    pub state: &'static str,
}

/// The template `jj log` reads the provenance with: the state, then
/// `@`'s parents.
const PROVENANCE_TEMPLATE: &str =
    r#"if(empty, "clean", "dirty") ++ " " ++ parents.map(|c| c.commit_id()).join(" ")"#;

/// The provenance in `jj log`'s output for [`PROVENANCE_TEMPLATE`],
/// refused unless `@` has one parent, whose commit is the build's.
fn parse_provenance(out: &str) -> Result<Provenance, String> {
    let mut words = out.split_whitespace();
    let state = match words.next() {
        Some("clean") => "clean",
        Some("dirty") => "dirty",
        _ => return Err(format!("jj printed '{}', not a state", out.trim())),
    };
    let parents: Vec<&str> = words.collect();
    match parents.as_slice() {
        [commit] if commit.len() == 40 && commit.chars().all(|c| c.is_ascii_hexdigit()) => {
            Ok(Provenance {
                commit: commit.to_string(),
                state,
            })
        }
        [commit] => Err(format!("jj printed '{commit}', not a commit id")),
        _ => Err(format!("`@` has {} parents, not one", parents.len())),
    }
}

/// Read the provenance of the work repo at `root` through `jj`, or warn
/// and carry none.
pub fn provenance(root: &Path) -> Option<Provenance> {
    let out = command("jj")
        .arg("-R")
        .arg(root)
        .args(["--color", "never", "--no-pager", "log", "-r", "@", "--no-graph"])
        .args(["-T", PROVENANCE_TEMPLATE])
        .output();
    let read = match out {
        Ok(out) if out.status.success() => {
            parse_provenance(&String::from_utf8_lossy(&out.stdout))
        }
        Ok(out) => Err(format!(
            "jj failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        )),
        Err(e) => Err(format!("jj did not run: {e}")),
    };
    match read {
        Ok(p) => Some(p),
        Err(e) => {
            eprintln!("xtask: warning: the provenance: {e}, so the build carries no commit");
            None
        }
    }
}

/// A cargo command from `root` with the provenance in its environment.
fn cargo_at(root: &Path, provenance: Option<&Provenance>) -> Command {
    let mut cmd = command(cargo());
    cmd.current_dir(root);
    if let Some(p) = provenance {
        cmd.env(COMMIT_VAR, &p.commit).env(STATE_VAR, p.state);
    }
    cmd
}

/// Run `cmd`, an error naming `what` when it fails.
fn status(mut cmd: Command, what: &str) -> Result<(), String> {
    let status = cmd
        .status()
        .map_err(|e| format!("{what} did not run: {e}"))?;
    match status.success() {
        true => Ok(()),
        false => Err(format!("{what} failed: {status}")),
    }
}

/// Run the validation, the full lists or the fast, in order, stopping
/// at the first failure.
pub fn validate(root: &Path, fast: bool) -> Result<String, String> {
    let (lists, name) = match fast {
        true => (FAST, "fast"),
        false => (FULL, "full"),
    };
    let provenance = provenance(root);
    for (i, args) in lists.iter().enumerate() {
        let what = format!("`cargo {}`", args.join(" "));
        eprintln!("validate: {what}");
        let mut cmd = cargo_at(root, provenance.as_ref());
        cmd.args(*args);
        status(cmd, &what).map_err(|e| {
            format!(
                "validate: {e}, command {} of {} ({name})",
                i + 1,
                lists.len()
            )
        })?;
    }
    Ok(format!(
        "validate: {} command(s) passed ({name})",
        lists.len()
    ))
}

/// The profile `--release` and `--profile` name, else `default`.
pub fn profile_of(release: bool, profile: Option<&str>, default: &str) -> String {
    match (release, profile) {
        (true, _) => "release".to_string(),
        (false, Some(name)) => name.to_string(),
        (false, None) => default.to_string(),
    }
}

/// The directory under cargo's target directory a profile's binaries
/// are in.
pub fn profile_dir(profile: &str) -> &str {
    match profile {
        "dev" | "test" => "debug",
        "bench" => "release",
        name => name,
    }
}

/// The name the binary of `profile` is installed under.
pub fn installed_name(profile: &str) -> String {
    match profile {
        "release" => BIN.to_string(),
        name => format!("{BIN}-{name}"),
    }
}

/// Cargo's target directory for the workspace at `root`, as `cargo
/// metadata` says, so a `target-dir` configured anywhere is followed.
fn target_dir(root: &Path) -> Result<PathBuf, String> {
    let out = command(cargo())
        .current_dir(root)
        .args(["metadata", "--format-version", "1", "--no-deps", "--offline"])
        .output()
        .map_err(|e| format!("cargo metadata did not run: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "cargo metadata failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    let meta: serde_json::Value = serde_json::from_slice(&out.stdout)
        .map_err(|e| format!("cargo metadata printed no JSON: {e}"))?;
    match meta.get("target_directory").and_then(|d| d.as_str()) {
        Some(dir) => Ok(PathBuf::from(dir)),
        None => Err("cargo metadata named no target_directory".to_string()),
    }
}

/// Where the build of `profile` leaves the binary.
pub fn binary(root: &Path, profile: &str) -> Result<PathBuf, String> {
    Ok(target_dir(root)?
        .join(profile_dir(profile))
        .join(format!("{BIN}{}", std::env::consts::EXE_SUFFIX)))
}

/// The build's arguments to cargo.
fn build_args(profile: &str) -> Vec<String> {
    ["build", "--profile", profile, "--locked"]
        .map(str::to_string)
        .to_vec()
}

/// Build `profile` with the provenance, returning the binary, checked
/// to be there.
pub fn build(root: &Path, profile: &str) -> Result<PathBuf, String> {
    let provenance = provenance(root);
    let mut cmd = cargo_at(root, provenance.as_ref());
    cmd.args(build_args(profile));
    status(cmd, &format!("`cargo {}`", build_args(profile).join(" ")))?;
    let bin = binary(root, profile)?;
    match bin.is_file() {
        true => Ok(bin),
        false => Err(format!(
            "the build passed and left no binary at '{}'",
            bin.display()
        )),
    }
}

/// Build `profile`, then run its binary with `args` in the current
/// directory, returning its exit code, a signal's death being 1.
pub fn run(root: &Path, profile: &str, args: &[OsString]) -> Result<u8, String> {
    let bin = build(root, profile)?;
    let status = command(&bin)
        .args(args)
        .status()
        .map_err(|e| format!("'{}' did not run: {e}", bin.display()))?;
    let code = match status.code() {
        Some(code) => code,
        None => 1,
    };
    Ok(match u8::try_from(code) {
        Ok(code) => code,
        Err(_) => 1,
    })
}

/// Cargo's bin directory, where `install` copies by default:
/// `$CARGO_HOME/bin`, else `~/.cargo/bin`.
fn install_dir() -> Result<PathBuf, String> {
    if let Some(home) = std::env::var_os("CARGO_HOME") {
        return Ok(PathBuf::from(home).join("bin"));
    }
    match std::env::var_os("HOME") {
        Some(home) => Ok(PathBuf::from(home).join(".cargo").join("bin")),
        None => Err("neither CARGO_HOME nor HOME is set, so `--dir` is needed".to_string()),
    }
}

/// Build `profile` and copy its binary into `dir`, else cargo's bin
/// directory, under [`installed_name`], by a temporary file beside it
/// renamed into place, so a running copy of the old binary is
/// undisturbed and a failed copy leaves it. `dry_run` says what it
/// would do and does nothing.
pub fn install(
    root: &Path,
    profile: &str,
    dir: Option<&Path>,
    dry_run: bool,
) -> Result<String, String> {
    let dir = match dir {
        Some(dir) => dir.to_path_buf(),
        None => install_dir()?,
    };
    let name = format!("{}{}", installed_name(profile), std::env::consts::EXE_SUFFIX);
    let dest = dir.join(&name);
    if dry_run {
        return Ok(format!(
            "install: would run `cargo {}`, then copy '{}' to '{}'",
            build_args(profile).join(" "),
            binary(root, profile)?.display(),
            dest.display()
        ));
    }
    if !dir.is_dir() {
        return Err(format!("no directory '{}' to install into", dir.display()));
    }
    let bin = build(root, profile)?;
    let tmp = dir.join(format!("{name}.new"));
    std::fs::copy(&bin, &tmp).map_err(|e| {
        format!(
            "copying '{}' to '{}': {e}",
            bin.display(),
            tmp.display()
        )
    })?;
    std::fs::rename(&tmp, &dest)
        .map_err(|e| format!("moving '{}' to '{}': {e}", tmp.display(), dest.display()))?;
    let version = command(&dest)
        .arg("-V")
        .output()
        .map(|out| String::from_utf8_lossy(&out.stdout).trim().to_string())
        .map_err(|e| format!("'{}' -V did not run: {e}", dest.display()))?;
    Ok(format!("install: {}\n{version}", dest.display()))
}

/// A completion request `run` hands to the binary: the profile it
/// would run, the words for the binary, its own name first, and the
/// cursor's index among them when the shell gave one.
#[derive(Debug, PartialEq, Eq)]
pub struct Forward {
    /// The profile `--release` or `--profile` named, else `dev`.
    pub profile: String,
    /// The words for the binary, the first standing for its name.
    pub words: Vec<String>,
    /// The cursor's index in `words`, when the shell passed one.
    pub index: Option<usize>,
}

/// Plan a completion forward from the words a shell passes, the
/// command's name first, and the cursor's index among them, or `None`
/// when the words are not `run`'s arguments and clap completes them.
///
/// - Only `run` is forwarded, the first word after the name.
/// - Its own flags, `--release`, `--profile NAME`, and
///   `--profile=NAME`, are skipped, and `--` ends them.
/// - The cursor on `run` or its flags is clap's, as is a word at the
///   cursor that starts with `-` before any argument, so `run --r<TAB>`
///   offers `--release`.
pub fn plan_forward(words: &[String], index: Option<usize>) -> Option<Forward> {
    // OK: with no index the shell completes the last word
    let cursor = index.unwrap_or(words.len().saturating_sub(1));
    if words.get(1).map(String::as_str) != Some("run") {
        return None;
    }
    let mut profile = "dev".to_string();
    let mut i = 2;
    while i < words.len() && i < cursor {
        let w = words[i].as_str();
        if w == "--" {
            i += 1;
            break;
        }
        if w == "--release" {
            profile = "release".to_string();
            i += 1;
        } else if w == "--profile" {
            if let Some(name) = words.get(i + 1) {
                profile = name.clone();
            }
            i += 2;
        } else if let Some(name) = w.strip_prefix("--profile=") {
            profile = name.to_string();
            i += 1;
        } else {
            break;
        }
    }
    if cursor < i || (cursor == i && words[i].starts_with('-') && words[i - 1] != "--") {
        return None;
    }
    let mut forwarded = vec![BIN.to_string()];
    forwarded.extend(words[i..].iter().cloned());
    Some(Forward {
        profile,
        words: forwarded,
        index: index.map(|n| n - i + 1),
    })
}

/// Answer a completion request for `run`'s arguments by asking the
/// binary it would run, in clap's completion mode, and exit with its
/// code. Anything else, and no request at all, returns, for clap to
/// complete. The binary is asked as it stands and never built, and one
/// that is not there offers nothing.
pub fn forward_completion(root: &Path) {
    if std::env::var_os("COMPLETE").is_none_or(|v| v.is_empty() || v == "0") {
        return;
    }
    let args: Vec<String> = std::env::args().collect();
    if args.get(1).map(String::as_str) != Some("--") {
        return;
    }
    let index = std::env::var("_CLAP_COMPLETE_INDEX")
        .ok()
        .and_then(|i| i.parse().ok());
    let Some(plan) = plan_forward(&args[2..], index) else {
        return;
    };
    let code = match binary(root, &plan.profile) {
        Ok(bin) if bin.is_file() => {
            let mut cmd = command(&bin);
            cmd.arg("--").args(&plan.words);
            if let Some(index) = plan.index {
                cmd.env("_CLAP_COMPLETE_INDEX", index.to_string());
            }
            match cmd.status().map(|s| s.code()) {
                Ok(Some(code)) => code,
                _ => 0,
            }
        }
        _ => 0,
    };
    std::process::exit(code);
}

#[cfg(test)]
mod tests {
    use super::*;

    fn w(s: &str) -> Vec<String> {
        s.split(' ').map(str::to_string).collect()
    }

    /// The provenance is the state and `@`'s one parent, and anything
    /// else is refused, saying what jj printed.
    #[test]
    fn the_provenance_is_read_from_jj() {
        let id = "a5026b80c1b2".repeat(4)[..40].to_string();
        assert_eq!(
            parse_provenance(&format!("dirty {id}\n")).unwrap(),
            Provenance {
                commit: id.clone(),
                state: "dirty"
            }
        );
        assert_eq!(parse_provenance(&format!("clean {id}")).unwrap().state, "clean");
        let merge = parse_provenance(&format!("clean {id} {id}")).unwrap_err();
        assert!(merge.contains("2 parents"), "{merge}");
        assert!(parse_provenance("clean").unwrap_err().contains("0 parents"));
        assert!(parse_provenance("clean xyz").unwrap_err().contains("not a commit id"));
        assert!(parse_provenance("").unwrap_err().contains("not a state"));
    }

    /// A profile's directory is cargo's, and its installed name the
    /// binary's with the profile appended, `release`'s plain.
    #[test]
    fn profiles_are_cargos() {
        assert_eq!(profile_dir("dev"), "debug");
        assert_eq!(profile_dir("test"), "debug");
        assert_eq!(profile_dir("release"), "release");
        assert_eq!(profile_dir("bench"), "release");
        assert_eq!(profile_dir("soak"), "soak");
        assert_eq!(installed_name("release"), "vc-x1");
        assert_eq!(installed_name("dev"), "vc-x1-dev");
        assert_eq!(installed_name("soak"), "vc-x1-soak");
        assert_eq!(profile_of(true, None, "dev"), "release");
        assert_eq!(profile_of(false, Some("soak"), "dev"), "soak");
        assert_eq!(profile_of(false, None, "dev"), "dev");
        assert_eq!(build_args("dev"), ["build", "--profile", "dev", "--locked"]);
    }

    /// Only `run`'s arguments are forwarded, its own flags skipped and
    /// the index shifted, and the cursor on `run`, its flags, or a flag
    /// before any argument is clap's.
    #[test]
    fn plan_forward_forms() {
        let p = plan_forward(&w("cx run st -s"), Some(3)).unwrap();
        assert_eq!(
            p,
            Forward {
                profile: "dev".to_string(),
                words: w("vc-x1 st -s"),
                index: Some(2),
            }
        );
        let p = plan_forward(&w("cx run --release sy"), Some(3)).unwrap();
        assert_eq!((p.profile.as_str(), p.words, p.index), ("release", w("vc-x1 sy"), Some(1)));
        let p = plan_forward(&w("cx run --profile soak st"), Some(4)).unwrap();
        assert_eq!((p.profile.as_str(), p.index), ("soak", Some(1)));
        let p = plan_forward(&w("cx run --profile=soak -- -"), Some(4)).unwrap();
        assert_eq!((p.profile.as_str(), p.words, p.index), ("soak", w("vc-x1 -"), Some(1)));
        let p = plan_forward(&w("cx run st"), None).unwrap();
        assert_eq!((p.words, p.index), (w("vc-x1 st"), None));
        assert_eq!(plan_forward(&w("cx run --r"), Some(2)), None, "run's own flag");
        assert_eq!(plan_forward(&w("cx run --profile "), Some(3)), None, "--profile's value");
        assert_eq!(plan_forward(&w("cx ru"), Some(1)), None, "the task's name");
        assert_eq!(plan_forward(&w("cx bump n"), Some(2)), None, "another task");
    }
}

